import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"국가 02 서남제작동맹","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-State-02.md","filePath":"world/Cast-State-02.md"}'),t={name:"world/Cast-State-02.md"};function h(o,l,u,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="국가-02-서남제작동맹" tabindex="-1">국가 02 서남제작동맹 <a class="header-anchor" href="#국가-02-서남제작동맹" aria-label="Permalink to &quot;국가 02 서남제작동맹&quot;">​</a></h1><p>중재자 강민서의 제작규격은 노동조합·건물조합·경비대가 평의회에서 부품과 복무를 교환할 때에만 구로·금천의 작업반을 움직인다.</p><h3 id="인물-정시우" tabindex="-1">인물 정시우 <a class="header-anchor" href="#인물-정시우" aria-label="Permalink to &quot;인물 정시우&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 천왕기지 제작원로</li><li>성격: 과묵하고 손끝의 공차로 사람을 기억한다. 규격서에 없는 임시 개조를 재능이 아니라 사고의 씨앗으로 본다.</li><li>개인 야망: 서울 전역 차륜·펌프 나사의 호환표를 천왕 원장 하나로 고정해 제작규격동맹의 뼈대를 만든다.</li><li>공포: 경비대가 군수 전용 나사를 따로 깎아 민간 수리망이 하루아침에 호환 불능이 되는 것.</li><li>통치 방식: 출고 부품마다 계측 도장을 찍고, 도장 없는 개조품은 천왕 유치선에 들이지 않는다.</li><li>핵심 관계: 강민서와는 규격 사제에 가깝고, 여의신정 열차장 최한결과 차륜 동맹이며, 장우석의 기록 날인 없이 규격 개정을 허용하지 않는다.</li><li>촉발 사건: 암사가 부품 대신 복구복무 등록을 요구하자 천왕 창고의 암사행 나사를 봉인하고 공개 호환표만 받겠다고 선언한다.</li><li>플레이어 개입: 봉인 나사의 실측 공차를 가져와 원로의 봉인을 풀거나, 군수 전용 나사의 숨은 도면을 찾아 규격 분열을 폭로할 수 있다.</li></ul><h3 id="인물-김나율" tabindex="-1">인물 김나율 <a class="header-anchor" href="#인물-김나율" aria-label="Permalink to &quot;인물 김나율&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 노동조합 서기</li><li>성격: 토론에서는 온화하나 합의 뒤의 태업 명단을 밤새 대조한다. 숙련 점수를 숨기는 반장을 조합의 적으로 본다.</li><li>개인 야망: 복구복무자의 시민권을 조합 명부에 먼저 올려 제작규격동맹이 군수가 아니라 노동 이동권으로 퍼지게 한다.</li><li>공포: 경비대가 파업 공방을 차단문으로 가두고 조합 명부를 군사호적으로 바꿔 쓰는 것.</li><li>통치 방식: 작업반 교대와 숙련 점수를 공개 칠판에 쓰고, 시민권 미등록 노동은 평의회 안건으로 올리지 않는다.</li><li>핵심 관계: 강민서의 교환 설계를 현장에서 집행하는 동맹이고, 백온의 난민 시민권 요구를 조합 표로 지지하며, 이강묵의 강경 동원령에는 원한을 품는다.</li><li>촉발 사건: 암사 요구가 내부 경비대를 자극하자 구로 공방 세 곳이 파업에 들어가고, 김나율은 평의회 의결 전까지 공구 반출을 막는다.</li><li>플레이어 개입: 파업 공방의 숙련 명부를 지켜 그의 시민권안을 통과시키거나, 태업 명단 조작을 밝혀 서기직을 흔들 수 있다.</li></ul><h3 id="인물-이강묵" tabindex="-1">인물 이강묵 <a class="header-anchor" href="#인물-이강묵" aria-label="Permalink to &quot;인물 이강묵&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 금천 경비대장</li><li>성격: 속도를 정의로 여기고, 토론이 길어지면 차단문부터 내린다. 부하 가족의 배급은 책임지되 조합 쪽 지연은 배신으로 읽는다.</li><li>개인 야망: 작업반을 상시 공병대로 전환하고 수리 규격을 군수 우선으로 재편해 제작동맹의 무력을 자신이 쥐게 한다.</li><li>공포: 노동조합이 부품 출고를 멈춰 경비대가 빈 차단문만 지키다 외곽 약탈에 뚫리는 것.</li><li>통치 방식: 치안 실적을 거리 게시판에 공개하지만, 비상 동원 암호는 장교 수첩에만 남겨 평의회를 우회한다.</li><li>핵심 관계: 강민서를 필요한 중재자로 보나 군수 독점에서는 경쟁하고, 암사 장교 장석윤과 차단문 전술을 거래하며, 김나율과는 명부를 둘러싼 원한이다.</li><li>촉발 사건: 암사의 복무 등록 압박이 전해지자 금천 차단문 전투조를 야간 편성하고 공구 창고에 이중 자물쇠를 채운다.</li><li>플레이어 개입: 비밀 무기 생산 수첩을 평의회에 넘기거나, 외곽 약탈을 함께 막아 그의 동원령을 정당화할 수 있다.</li></ul><h3 id="인물-박소언" tabindex="-1">인물 박소언 <a class="header-anchor" href="#인물-박소언" aria-label="Permalink to &quot;인물 박소언&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 건물조합 대표</li><li>성격: 실리를 즐기되 지붕과 전력 간선의 안전을 흥정 카드로 쓰지 않는다. 숙련공보다 거주 표를 얕보는 사람을 오래 기억한다.</li><li>개인 야망: 공방 건물과 주거 쉘의 수리 순서를 조합 추첨으로 고정해, 군수 작업반이 민가 전력을 선점하지 못하게 한다.</li><li>공포: 자체 원수가 끊긴 뒤 건물 저수조가 마르면 조합원이 여의신정 급수계약의 볼모가 되는 것.</li><li>통치 방식: 전력 장치와 펌프 설치를 건물 단위로 공개 입찰하고, 낙찰 공방은 숙련 점수를 노동조합과 공유해야 한다.</li><li>핵심 관계: 강민서의 공정 분할을 건물 쪽에서 받쳐 주는 동맹이고, 한지온의 원수 배급표에 의존하며, 최다인의 공병 차출이 지붕 공사를 빼앗을 때 충돌한다.</li><li>촉발 사건: 서부 급수계약 만료 소문이 돌자 건물 저수조를 봉인하고 여의신정 배급 대표와의 직접 협상을 요구한다.</li><li>플레이어 개입: 대체 저수 펌프를 구해 봉인을 풀거나, 입찰 담합 장부를 폭로해 조합 추첨을 다시 열 수 있다.</li></ul><h3 id="인물-최다인" tabindex="-1">인물 최다인 <a class="header-anchor" href="#인물-최다인" aria-label="Permalink to &quot;인물 최다인&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 공병 작업반장</li><li>성격: 대담하고 손빠르며 계급 배지보다 용접 이음을 본다. 완성된 차단문을 정치 협상용으로 열어 두라는 명령을 싫어한다.</li><li>개인 야망: 작업반 전환 공병대를 규격 복구의 선봉으로 만들어, 무력 정복 없이 남서 외곽 선로를 제작동맹 표준으로 깐다.</li><li>공포: 자체 식량이 바닥나 공병이 군량 징발대로 바뀌고 복구 노동의 시민권이 사라지는 것.</li><li>통치 방식: 차단문과 선로 보수를 낮 교대에 공개하고, 야간 무장 차출은 평의회 세 조합의 도장이 있어야 따른다.</li><li>핵심 관계: 정시우에게 공차 사제로 묶여 있고, 이강묵의 야간 편성을 마지막에야 승인하며, 박소언의 지붕 공사 인력과 작업반을 나눠 쓴다.</li><li>촉발 사건: 뚝도 펌프 점검망이 멈추자 천왕 공병을 성수 방향으로 보낼지, 금천 차단문을 굳힐지를 작업반 투표에 부친다.</li><li>플레이어 개입: 외곽 선로 보수에 동행해 그의 표준 깔기를 돕거나, 군량 징발 명령을 증거로 남겨 작업반 투표를 막을 수 있다.</li></ul><h3 id="인물-장우석" tabindex="-1">인물 장우석 <a class="header-anchor" href="#인물-장우석" aria-label="Permalink to &quot;인물 장우석&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 수리규격 감사기록관</li><li>성격: 원칙적이고 문장의 빈칸을 증오한다. 구두로 합의한 호환을 원장에 올리지 않는 원로를 규격의 적으로 부른다.</li><li>개인 야망: 제작규격동맹의 모든 개정에 감사 날인과 종료 조건을 붙여, 군수 비상 핑계로 규격이 사라지지 않게 한다.</li><li>공포: 위조 계측 도장 하나가 천왕 원장 전체를 무효로 만들어 제작동맹이 부품 봉쇄로 쪼개지는 것.</li><li>통치 방식: 규격 사본을 평의회와 공방에 동시에 배포하고, 비상 개정도 사흘 안의 재측정 없이는 무효라고 못 박는다.</li><li>핵심 관계: 정시우의 계측 도장을 검증하는 계약이고, 정유라의 종료 조건 문장을 참고하며, 이강묵의 암호 동원 수첩을 원장 밖으로 밀어내려 한다.</li><li>촉발 사건: 유력 공방의 시험 부품에서 의도적 결함이 발견되자 출고 전면 재측정을 선언하고 평의회 표결을 중단시킨다.</li><li>플레이어 개입: 결함 부품의 제조 공방을 추적하거나, 감사 날인을 위조한 자를 잡아 기록관의 권한을 세울 수 있다.</li></ul><h3 id="인물-임채원" tabindex="-1">인물 임채원 <a class="header-anchor" href="#인물-임채원" aria-label="Permalink to &quot;인물 임채원&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 방호복 직능 대표</li><li>성격: 실용적이고 바느질 간격으로 위험을 가늠한다. 방호복을 전리품처럼 쌓아 두는 장교를 재앙처럼 피한다.</li><li>개인 야망: 방호복과 필터 규격을 의료·정수 작업반까지 열어, 복구복무자가 군복이 아니어도 시민으로 숨 쉬게 한다.</li><li>공포: 필터 원단이 동부 보호계약에 묶여 구로 작업반이 탁수와 분진 속에 방치되는 것.</li><li>통치 방식: 출고 수량을 조합 칠판에 쓰고, 군수 우선 배정은 방재 표본이 기준을 넘을 때만 허용한다.</li><li>핵심 관계: 마곡 인증관 최은재와 필터 성능 검증을 동맹으로 나누고, 강민서의 공정 분할에서 방호 공정을 맡으며, 한소미의 가죽 공방과 원자재 교환을 경쟁한다.</li><li>촉발 사건: 폭우 뒤 탁수 소문이 퍼지자 필터 재고를 정수 작업반에 먼저 풀지, 경비대 차단문조에 먼저 줄지를 직능 투표에 부친다.</li><li>플레이어 개입: 대체 원단을 구하거나, 군수 창고에 숨긴 필터를 폭로해 직능 투표의 방향을 바꿀 수 있다.</li></ul><h3 id="인물-한지온" tabindex="-1">인물 한지온 <a class="header-anchor" href="#인물-한지온" aria-label="Permalink to &quot;인물 한지온&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 금천 원수식량 시민대표</li><li>성격: 자비롭지만 공복 상태의 숫자 놀음을 용서하지 않는다. 부품 출고를 자랑하는 날에도 저수조와 배급 솥을 먼저 확인한다.</li><li>개인 야망: 제작동맹의 수리 수출을 원수·식량 장기 계약과 강제로 묶어, 자체 생산이 없는 약점을 평의회 의결로 메운다.</li><li>공포: 한 계절의 흉작과 단수가 겹쳐 작업반이 군량 징발로 민가를 훑는 것.</li><li>통치 방식: 배급 솥과 우물 수위를 매일 공개하고, 외곽 조달 행렬에는 조합원 가족과 난민 명부를 함께 태운다.</li><li>핵심 관계: 한재목의 서부 급수계약에 시민 최저선을 요구하는 빚을 졌고, 백온의 남하 행렬을 수용 동맹으로 맞으며, 박소언의 건물 저수조 봉인을 함께 감시한다.</li><li>촉발 사건: 북부 식량 부족 소문이 금천 배급 솥까지 흔들자 한지온은 부품 수출 중지를 평의회에 올리고 여의신정 바지선 배급을 요청한다.</li><li>플레이어 개입: 조달 행렬을 호송해 솥을 채우거나, 군량 징발 밀지를 찾아 시민대표의 중지안을 통과시킬 수 있다.</li></ul><h3 id="인물-허다온" tabindex="-1">인물 허다온 <a class="header-anchor" href="#인물-허다온" aria-label="Permalink to &quot;인물 허다온&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 천왕기지 차륜 정비사</li><li>성격: 공차로 사람을 기억하고, 규격서에 없는 임시 깎기를 사고의 씨앗으로 본다. 말수는 적고 제동 시험으로 대답한다.</li><li>개인 야망: 서울 전역 차륜 나사의 호환 실측을 천왕 정비표로 고정해 제작규격동맹의 손끝이 된다.</li><li>공포: 경비대가 군수 전용 나사를 따로 깎아 민간 수리망이 하루아침에 호환 불능이 되는 것.</li><li>통치 방식: 출고 차륜마다 계측 도장을 찍고, 도장 없는 개조품은 유치선에 들이지 않는다.</li><li>핵심 관계: 정시우에게 공차 사제로 묶여 있고, 최다인의 공병 작업반에 차륜을 대며, 최한결의 신정 보수열차와 밀봉·차륜을 계약으로 나눈다.</li><li>촉발 사건: 암사가 부품 대신 복무 등록을 요구하자 허다온은 천왕 차륜 창고의 암사행 나사를 봉인한다.</li><li>플레이어 개입: 봉인 나사의 실측 공차를 가져와 봉인을 풀거나, 군수 전용 나사의 숨은 도면을 찾아 규격 분열을 폭로할 수 있다.</li></ul><h3 id="인물-구찬솔" tabindex="-1">인물 구찬솔 <a class="header-anchor" href="#인물-구찬솔" aria-label="Permalink to &quot;인물 구찬솔&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 공구시장 물류상</li><li>성격: 상자 무게로 속임수를 읽고, 숙련 점수를 숨기는 반장의 화물은 선석이 아니라 골목에 내려 놓는다. 실리를 즐기되 지붕 못을 군수 상자에 섞지 않는다.</li><li>개인 야망: 공구와 전력 장치의 운송을 조합 추첨 원장으로 묶어 군수 작업반이 민가 수리를 선점하지 못하게 한다.</li><li>공포: 자체 원수가 끊긴 뒤 시장 저수조가 마르면 물류가 여의신정 급수계약의 볼모가 되는 것.</li><li>통치 방식: 출고 상자를 노동조합 칠판에 공개하고, 시민권 미등록 운송은 평의회 안건으로 올리지 않는다.</li><li>핵심 관계: 김나율의 숙련 명부를 화물 허가에 묶는 계약이고, 박소언의 건물 수리 자재를 우선 배차하며, 이강묵의 이중 자물쇠가 창고를 잠글 때 충돌한다.</li><li>촉발 사건: 암사 요구가 내부 경비대를 자극하자 구로 공방 세 곳이 파업에 들어가고, 구찬솔은 공구 반출을 평의회 의결 전까지 막는다.</li><li>플레이어 개입: 파업 공방의 숙련 명부를 지켜 그의 허가를 통과시키거나, 상자 무게 조작을 밝혀 물류 창구를 흔들 수 있다.</li></ul><h3 id="인물-진우람" tabindex="-1">인물 진우람 <a class="header-anchor" href="#인물-진우람" aria-label="Permalink to &quot;인물 진우람&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 금천 공방의무원</li><li>성격: 분진 기침을 용접 불꽃보다 먼저 듣고, 방호 필터를 전리품처럼 쌓는 장교를 재앙처럼 피한다. 자비롭지만 공복 상태의 숫자 놀음을 용서하지 않는다.</li><li>개인 야망: 방호 필터와 공방 진료를 복구복무자의 시민권 조건으로 묶어 제작동맹이 군복이 아니어도 숨 쉬게 한다.</li><li>공포: 필터 원단이 동부 보호계약에 묶여 금천 작업반이 탁수와 분진 속에 방치되는 것.</li><li>통치 방식: 진료 인원과 필터 출고를 같은 칠판에 쓰고, 군수 우선 배정은 방재 표본이 기준을 넘을 때만 허용한다.</li><li>핵심 관계: 임채원의 필터 규격을 진료에 적용하는 사제에 가깝고, 한지온의 배급 솥이 비면 의무 배식을 열며, 최은재의 필터 인증 도장이 떨어지면 출고를 잠근다.</li><li>촉발 사건: 폭우 뒤 탁수 소문이 퍼지자 진우람은 필터 재고를 정수 작업반 진료에 먼저 풀지, 차단문조에 먼저 줄지를 직능 투표에 부친다.</li><li>플레이어 개입: 대체 원단을 구하거나, 군수 창고에 숨긴 필터를 폭로해 투표의 방향을 바꿀 수 있다.</li></ul><h3 id="인물-채리울" tabindex="-1">인물 채리울 <a class="header-anchor" href="#인물-채리울" aria-label="Permalink to &quot;인물 채리울&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 공방 순찰대 조장</li><li>성격: 차단문 녹보다 태업 명단의 빈칸을 먼저 의심하고, 토론이 길어져도 공구 창고 앞에서 총을 내리지 않는다. 부하 가족의 배급은 책임지되 조합 쪽 지연을 배신으로 읽지는 않는다.</li><li>개인 야망: 공방 순찰을 평의회 세 조합의 도장 아래 묶어, 경비대가 파업 공방을 가두지 못하게 한다.</li><li>공포: 노동조합이 부품 출고를 멈춰 순찰대가 빈 차단문만 지키다 외곽 약탈에 뚫리는 것.</li><li>통치 방식: 주간 순찰 경로를 공개하되, 야간 무장 차출은 김나율의 명부와 이강묵의 암호가 동시에 있어야 따른다.</li><li>핵심 관계: 이강묵의 차단문 지휘를 받되 김나율의 시민권 명부를 지키는 이중 계약이고, 구찬솔의 공구 반출 봉쇄를 순찰로 받친다.</li><li>촉발 사건: 암사의 복무 등록 압박이 전해지자 채리울은 야간 전투조 편성을 거부하고 파업 공방 세 곳의 차단문만 연다.</li><li>플레이어 개입: 외곽 약탈을 함께 막아 그의 이중 계약을 정당화하거나, 비밀 병기 생산 수첩을 평의회에 넘겨 조장을 교체할 수 있다.</li></ul><h3 id="인물-표강호" tabindex="-1">인물 표강호 <a class="header-anchor" href="#인물-표강호" aria-label="Permalink to &quot;인물 표강호&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 제작규격 전령</li><li>성격: 규격 사본의 계측 숫자를 외우고, 구두로 합의한 호환을 원장에 올리지 않는 원로를 규격의 적으로 부른다. 봉인 끈이 젖으면 다시 떠난다.</li><li>개인 야망: 제작규격동맹의 모든 개정 통지를 자신이 날인하는 전령망에만 유효하게 해 군수 비상 핑계로 규격이 사라지지 않게 한다.</li><li>공포: 위조 계측 도장 하나가 천왕 원장 전체를 무효로 만들어 전령망이 부품 봉쇄의 나팔이 되는 것.</li><li>통치 방식: 규격 사본을 평의회와 공방에 동시에 배달하고, 비상 개정도 사흘 안의 재측정 통지가 없으면 달리지 않는다.</li><li>핵심 관계: 장우석의 감사 날인을 현장에서 배달하는 계약이고, 정시우의 계측 도장을 검증 전갈로 지키며, 강민서의 교환 설계를 봉인 상태로만 나른다.</li><li>촉발 사건: 유력 공방의 시험 부품에서 의도적 결함이 발견되자 표강호는 출고 전면 재측정 전갈을 먼저 돌리고 평의회 표결 방송을 멈춘다.</li><li>플레이어 개입: 결함 부품의 제조 공방을 추적하거나, 전갈 날인을 위조한 자를 잡아 전령망을 세울 수 있다.</li></ul><h3 id="인물-명소이" tabindex="-1">인물 명소이 <a class="header-anchor" href="#인물-명소이" aria-label="Permalink to &quot;인물 명소이&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 남서 외곽선로 탐사원</li><li>성격: 침목의 균열로 우회 가능 여부를 읽고, 완성된 차단문을 정치 협상용으로 열어 두라는 명령을 싫어한다. 대담하고 손빠르다.</li><li>개인 야망: 남서 외곽 선로를 제작동맹 표준 침목으로 잇는 탐사 원장을 만들어 무력 정복 없이 표준을 깐다.</li><li>공포: 자체 식량이 바닥나 탐사조가 군량 징발대로 바뀌고 복구 노동의 시민권이 사라지는 것.</li><li>통치 방식: 낮 교대에 선로 보수를 공개하고, 야간 무장 탐사는 평의회 세 조합의 도장이 있어야 따른다.</li><li>핵심 관계: 최다인에게 공차 사제로 묶여 외곽 깔기를 나누고, 허다온의 차륜 시운전에 맞춰 침목을 갈아 끼우며, 한지온의 조달 행렬을 우회로로 안내한다.</li><li>촉발 사건: 뚝도 펌프 점검망이 멈추자 명소이는 천왕 탐사조를 성수 방향으로 보낼지, 금천 차단문을 굳힐지를 조원 투표에 부친다.</li><li>플레이어 개입: 외곽 선로 탐사에 동행해 그의 표준 깔기를 돕거나, 군량 징발 명령을 증거로 남겨 투표를 막을 수 있다.</li></ul><h3 id="인물-제하온" tabindex="-1">인물 제하온 <a class="header-anchor" href="#인물-제하온" aria-label="Permalink to &quot;인물 제하온&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 숙련점수 원장 기록관</li><li>성격: 원칙적이고 문장의 빈칸을 증오한다. 태업 명단을 밤새 대조하는 서기의 숫자를 원장 밖으로 밀어내지 않는다.</li><li>개인 야망: 복구복무자의 시민권과 숙련 점수를 같은 원장에 올려 제작규격동맹이 군수가 아니라 노동 이동권으로 퍼지게 한다.</li><li>공포: 경비대가 파업 공방을 가두고 조합 명부를 군사호적으로 바꿔 쓰는 것.</li><li>통치 방식: 작업반 교대와 숙련 점수를 공개 칠판에 옮기고, 시민권 미등록 노동은 평의회 안건 원장에 올리지 않는다.</li><li>핵심 관계: 김나율의 서기 명부를 원장으로 고정하는 계약이고, 장우석의 규격 날인과 숙련 점수를 교차검증하며, 백온의 난민 시민권 요구를 기록으로 지지한다.</li><li>촉발 사건: 암사 요구가 내부 경비대를 자극하자 제하온은 평의회 의결 전까지 공구 반출 원장을 봉인한다.</li><li>플레이어 개입: 숙련 명부를 지켜 시민권안을 통과시키거나, 태업 명단 조작을 밝혀 기록관을 흔들 수 있다.</li></ul><h3 id="인물-변시람" tabindex="-1">인물 변시람 <a class="header-anchor" href="#인물-변시람" aria-label="Permalink to &quot;인물 변시람&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 대합실 역장</li><li>성격: 승강장 분진으로 작업반 규모를 읽고, 급수열차를 정치 순위로 미루는 명령을 참지 못한다. 시간표의 빈칸을 사람보다 먼저 메운다.</li><li>개인 야망: 구로 대합실을 부품 출고·시민권 등록·배급 솥이 한 지붕에서 서명되는 제작동맹의 대면 창구로 만든다.</li><li>공포: 자체 원수가 끊겨 대합실 저수조가 마르면 역 대기열이 여의신정 급수계약의 인질이 되는 것.</li><li>통치 방식: 대합실 배급과 출고 창구를 매일 공개하고, 군수 화차는 시민권 등록 창구가 닫힌 뒤에만 붙인다.</li><li>핵심 관계: 구찬솔의 공구 화차를 승강장 순번에 올리고, 한지온의 배급 솥을 대합실 한쪽에 두며, 유세진의 서부 급수열차 우회를 구로에서 받는다.</li><li>촉발 사건: 서부 급수계약 만료 소문이 돌자 변시람은 대합실 저수조를 봉인하고 여의신정 배급 대표와의 직접 협상을 요구한다.</li><li>플레이어 개입: 대체 저수 펌프를 구해 봉인을 풀거나, 창구 담합 장부를 폭로해 역 추첨을 다시 열 수 있다.</li></ul><h3 id="인물-표예담" tabindex="-1">인물 표예담 <a class="header-anchor" href="#인물-표예담" aria-label="Permalink to &quot;인물 표예담&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 천왕기지 유치배차 실무장</li><li>성격: 선로 진동으로 열차의 거짓을 읽고, 수리 물자를 군수 화차로 위장하는 명령을 모욕으로 듣는다. 과묵하고 출고 시각을 어기는 조합을 오래 기억한다.</li><li>개인 야망: 천왕 유치선을 규격 도장 화물만 오가는 순환 배차망으로 만들어 제작규격동맹의 동맥이 된다.</li><li>공포: 용산 중계가 막히면 천왕 유치선이 가득 차 공병열차와 급수열차가 동시에 갇히는 것.</li><li>통치 방식: 정비·공병·배급 순서를 매일 공개하고, 도장 없는 군수 개조는 유치선 바깥으로 밀어낸다.</li><li>핵심 관계: 허다온의 차륜 출고를 배차판에서 보증하고, 정시우의 계측 도장에 배차를 묶으며, 박태겸의 중계 창구와 외곽 열차를 나눈다.</li><li>촉발 사건: 암사가 복무 등록을 요구하자 표예담은 천왕발 암사행 나사를 잠그고 서남 규격만 받겠다고 배차판에 쓴다.</li><li>플레이어 개입: 대체 차륜을 구해 순환 배차를 살리거나, 봉쇄 유치선의 밀반출 장부를 폭로할 수 있다.</li></ul><h3 id="인물-명다해" tabindex="-1">인물 명다해 <a class="header-anchor" href="#인물-명다해" aria-label="Permalink to &quot;인물 명다해&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 금천 배급솥 시장 중개인</li><li>성격: 국자 자국이 솥마다 다르면 장부 숫자를 접고, 뚜껑 번호가 지워진 솥은 중개 테이블에서 뺀다. 흉작 쪽지가 돌면 국자를 기둥에 묶어 둔다.</li><li>개인 야망: 뚜껑 번호가 찍힌 솥만 불을 받게 해, 수리 수출이 국자 수보다 앞서는 날을 시장에서 막는다.</li><li>공포: 빈 솥이 사흘을 넘기면 작업반이 시장 국자를 징발 막대로 바꾸는 것.</li><li>통치 방식: 뚜껑 번호가 없는 솥은 불을 피우지 않고, 외곽 수레는 국자가 기둥에서 풀린 뒤에만 보낸다.</li><li>핵심 관계: 한지온의 시민 최저선을 솥 수로 집행하는 계약이고, 박소언의 건물 저수 봉인을 시장 기둥에서 함께 본다. 한재목의 서부 급수계약에 국자 숫자를 요구한다.</li><li>촉발 사건: 금천 솥 세 개의 국자가 같은 아침 사라지자 명다해는 수리 수출 수레의 바퀴를 시장에 묶고 바지선 배급을 창구에 요구했다.</li><li>플레이어 개입: 사라진 국자를 기둥에 다시 묶거나, 수출 수레 바퀴를 풀어 달라는 쪽지의 발주자를 시장에 세울 수 있다.</li></ul><h3 id="인물-제문석" tabindex="-1">인물 제문석 <a class="header-anchor" href="#인물-제문석" aria-label="Permalink to &quot;인물 제문석&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 분진진료소 의무장</li><li>성격: 바느질 간격으로 방호복의 위험을 가늠하고, 진료 기록을 군수 명부로 달라는 장교를 문으로 밀어낸다. 실용적이고 손이 빠르다.</li><li>개인 야망: 분진 진료와 필터 교환을 의료·정수 작업반까지 열어 복구복무자가 군복이 아니어도 시민으로 숨 쉬게 한다.</li><li>공포: 가짜 약품이 공방 골목에 퍼져 진료소가 강국 보호를 받는 제조망의 창구가 되는 것.</li><li>통치 방식: 환자 중증도와 필터 교체 주기를 함께 게시하고, 인증 도장 없는 약은 약장에 들이지 않는다.</li><li>핵심 관계: 진우람의 금천 의무와 환자 이송을 나누고, 임채원의 방호 출고를 진료 수량에 맞추며, 류은비의 약효 검증을 구로 표본으로 돕는다.</li><li>촉발 사건: 가짜 약품 소문이 북산에서 구로 공방까지 번지자 제문석은 약장을 이중 봉인하고 마곡 재현 실험을 요구한다.</li><li>플레이어 개입: 재현 실험의 원본 기록을 가져와 약장을 열거나, 비공개 구매 조항을 숨긴 공방을 폭로할 수 있다.</li></ul><h3 id="인물-변주아" tabindex="-1">인물 변주아 <a class="header-anchor" href="#인물-변주아" aria-label="Permalink to &quot;인물 변주아&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 구로 전력간선 발전운전장</li><li>성격: 주파수 바늘이 한 칸만 내려가도 말을 멈추고 차단기 손잡이를 잡는다. 군수 작업반의 심야 청을 부하표 바깥에 적지 않는다.</li><li>개인 야망: 주파수 최저선을 빨간 실로 나눠 공방과 쉘이 같은 밤에 멈추지 않게 하고, 군수 회로가 민가 펌프를 삼키지 못하게 한다.</li><li>공포: 빨간 실 아래의 주파수가 사흘을 넘기면 발전 손잡이가 여의신정 창구의 담보 번호가 되는 것.</li><li>통치 방식: 주파수 최저선을 빨간 실로 계기판에 표시하고, 군수 회로는 민가 펌프 바늘이 안정된 뒤에만 올린다.</li><li>핵심 관계: 박소언의 입찰 결과를 회로 색으로 집행하는 지휘를 받고, 허다온의 시운전에 심야 주파수만 빌려 준다. 이강묵의 야간 편성이 민가 회로를 빼면 손잡이를 내린다.</li><li>촉발 사건: 주파수 바늘이 빨간 실 아래로 떨어지자 변주아는 군수 회로를 내리고 배급 창구에 부하표를 들고 갔다.</li><li>플레이어 개입: 민가 펌프 바늘이 안정될 회로를 빌려 오거나, 부하표에 숨은 군수 줄을 창구에 펼 수 있다.</li></ul><h3 id="인물-종마루" tabindex="-1">인물 종마루 <a class="header-anchor" href="#인물-종마루" aria-label="Permalink to &quot;인물 종마루&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 가짜 펌프 부품 피해자 대표</li><li>성격: 불량 차륜의 진동을 손끝으로 읽고, 규격 도장을 산 가격으로 부르는 상인을 용서하지 않는다. 숙련공의 손가락보다 창고 봉인을 먼저 확인한다.</li><li>개인 야망: 불량 펌프 부품의 제조 공방과 유통 경로를 공개 원장에 올려, 수리 규격이 가짜 도장의 방패가 되지 않게 한다.</li><li>공포: 탁수 구간에 넣은 가짜 패킹이 터져 구로 저수조가 비고, 그 사고가 군수 작업반의 강제 동원 명분이 되는 것.</li><li>통치 방식: 피해 명부와 회수 부품을 같은 봉인함에 넣고, 감정은 노동조합과 규격 감사관이 동시에 볼 때만 연다.</li><li>핵심 관계: 장우석의 수리규격 원장에 불량 목록을 올리고, 강민서의 규격 통일안을 피해 쪽에서 압박하며, 뚝도의 류다인과 같은 가짜 부품의 양쪽 끝을 증언한다.</li><li>촉발 사건: 여름의 탁수와 가짜 약에서 폭우 뒤 불량 패킹이 서부 관로에 섞이자, 종마루는 구로 공방의 피해자 명부를 들고 출고 중지를 요구한다.</li><li>플레이어 개입: 가짜 도장 원판을 찾아 그의 출고 중지를 뒷받침하거나, 명부에 없는 공방을 끼워 넣은 증거를 폭로할 수 있다.</li></ul><h3 id="인물-고모래" tabindex="-1">인물 고모래 <a class="header-anchor" href="#인물-고모래" aria-label="Permalink to &quot;인물 고모래&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 복구복무 거부 증언 서기</li><li>성격: 가족 단위 등록 명부의 빈칸을 보면 펜을 멈추고, 숙련을 병적으로 바꾸는 문장을 오래 밑줄 친다. 큰소리는 내지 않되 서명란은 비워 둔다.</li><li>개인 야망: 자발적 성인 복구복무와 시민권 계약을 조합 헌장에 남겨, 가족 분리 등록이 제작평의회를 통과하지 못하게 한다.</li><li>공포: 거부 증언이 탈주 명단으로 바뀌고, 그 명단이 암사 장교망의 징발 근거가 되는 것.</li><li>통치 방식: 증언은 노동조합 서기와 시민대표가 함께 들을 때만 기록하고, 군사용 호적 양식은 받아도 철하지 않는다.</li><li>핵심 관계: 김나율의 조합 서기와 거부 문장을 나누고, 백온의 가족 투표를 지지하며, 배우진의 강제등록 요구를 증언석에서 막는다.</li><li>촉발 사건: 붕괴 2년 군사호적 논쟁에서 암사 군사파가 가족 단위 복무등록을 요구하자, 고모래는 구로 작업반의 거부 증언을 봉인 원장에 남긴다.</li><li>플레이어 개입: 가족 명부를 되찾아 그의 거부를 증명하거나, 증언을 탈주 명단으로 고친 자를 찾아 서기를 교체할 수 있다.</li></ul><h3 id="인물-배온결" tabindex="-1">인물 배온결 <a class="header-anchor" href="#인물-배온결" aria-label="Permalink to &quot;인물 배온결&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 공신 보상 원장 서기</li><li>성격: 창건 직후의 배급권 요구를 공로와 물자로 나눠 적고, 세습 칸이 비어 있으면 줄을 그어 지운다. 보상 잔치를 일의 끝으로 보지 않는다.</li><li>개인 야망: 공신 보상을 관직이 아니라 숙련 점수와 한시 배급으로만 남게 해, 제작동맹이 창건자 친위국이 되지 않게 한다.</li><li>공포: 과도한 세습권이 평의회를 쪼개고, 그 공백을 경비대가 군수독재로 메우는 것.</li><li>통치 방식: 보상 원장은 노동·건물·경비 삼자가 동시에 날인해야 유효하고, 세습 문구는 난외에만 적힌 채 본문에 올리지 않는다.</li><li>핵심 관계: 정시우의 원로 권한을 보상과 분리하고, 장우석의 규격 원장과 배급 칸을 맞추며, 한소미의 공방 보상 요구를 참고하되 세습은 거절한다.</li><li>촉발 사건: 붕괴 4년 공신의 겨울에 창건 공신들이 관직과 세습권을 요구하자, 배온결은 구로 원장의 세습 칸을 공란으로 봉한다.</li><li>플레이어 개입: 숙련 점수 장부를 가져와 한시 배급안을 통과시키거나, 숨겨진 세습 난외를 폭로해 원장 서기를 끌어내릴 수 있다.</li></ul><h3 id="인물-류겨레" tabindex="-1">인물 류겨레 <a class="header-anchor" href="#인물-류겨레" aria-label="Permalink to &quot;인물 류겨레&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 난민 수용 전령</li><li>성격: 남하 행렬의 발자국 수보다 아이 배급통을 먼저 세고, 수용을 부품 대금과 바꾸자는 제안을 모욕으로 듣는다. 경로는 짧게, 거절은 분명하게 전한다.</li><li>개인 야망: 북부 난민의 하룻밤 숙영과 아침 급수를 조합 추첨으로 열어, 제작동맹이 암사의 복무 재등록 창구가 되지 않게 한다.</li><li>공포: 행렬이 금천 차단문에 막힌 채 얼고, 그 죽음이 자체 원수 부족을 가리는 통계가 되는 것.</li><li>통치 방식: 수용 쪽지는 시민대표와 노동조합이 함께 찍어야 유효하고, 경비대 단독 통행증은 전령 가방에 넣지 않는다.</li><li>핵심 관계: 한지온의 원수·식량 배분을 행렬에 연결하고, 백온의 남하를 금천 쪽에서 맞으며, 강민서의 시민권 연대를 전령로로 실어 나른다.</li><li>촉발 사건: 가을의 북산 행렬에서 복무계약 만료와 식량 부족이 겹치자, 류겨레는 구로-금천 숙영 쪽지를 들고 차단문 앞에 선다.</li><li>플레이어 개입: 하룻밤 식량과 급수통을 구해 그의 숙영을 열거나, 전령 쪽지를 복무 등록서로 바꾼 자를 밝혀 경로를 끊을 수 있다.</li></ul><h3 id="인물-엄누리" tabindex="-1">인물 엄누리 <a class="header-anchor" href="#인물-엄누리" aria-label="Permalink to &quot;인물 엄누리&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 후계시험 부품 감정 직공</li><li>성격: 시험 차륜의 미세 균열을 눈으로 먼저 찾고, 합격 도장을 밤에 찍으라는 속삭임을 배신으로 본다. 침묵하되 불량품은 작업대 위에 남겨 둔다.</li><li>개인 야망: 북부 후계시험 부품의 조작 흔적을 규격 원장에 공개해, 숙련 승계가 비밀 장교망의 손에서 벗어나게 한다.</li><li>공포: 조작된 부품이 창동 시험에 들어가 원로 자리가 바뀌고, 그 결과가 용산 배차표의 검은 칸과 하나로 묶이는 것.</li><li>통치 방식: 감정은 두 직공이 교차로 하고, 야간 단독 출고는 유치선 감독의 요청이어도 거부한다.</li><li>핵심 관계: 허다온의 차륜 정비 일지에 균열을 옮기고, 김도윤의 공개 기술시험을 지키려 하며, 박태겸의 양자 승계안이 시험 조작과 겹치는지 의심한다.</li><li>촉발 사건: 겨울의 검은 배차표에서 북부 후계시험 부품 조작이 드러나자, 엄누리는 천왕 창고의 동일 균열 부품을 봉인해 증언한다.</li><li>플레이어 개입: 균열 부품을 창동까지 호송해 그의 감정을 확정하거나, 야간 출고 일지를 위조한 자를 찾아 직공을 고립시킬 수 있다.</li></ul><h3 id="인물-여시온" tabindex="-1">인물 여시온 <a class="header-anchor" href="#인물-여시온" aria-label="Permalink to &quot;인물 여시온&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 제작헌장 전령</li><li>성격: 깃발보다 헌장 사본의 무게를 믿고, 선언 문구가 작업장 규칙과 어긋나면 전달을 하루 미룬다. 경로는 공개하고 가방 속 순서는 숨기지 않는다.</li><li>개인 야망: 독자 헌장의 수리 규격과 복구 노동 시민권을 기록청 인준 이전에 조합 게시판에 붙여, 법통 빚이 생산 규칙을 삼키지 못하게 한다.</li><li>공포: 인준을 미끼로 헌장 사본이 회수되고, 평의회가 도성 정치의 하위 작업반으로 떨어지는 것.</li><li>통치 방식: 사본은 노동조합·건물조합·경비대가 각각 한 장씩 받고, 한 장만 남은 전달은 출발하지 않는다.</li><li>핵심 관계: 표강호의 규격 전령로와 경로를 나누고, 강민서의 제작평의회 선언을 구로 골목에 붙이며, 윤서린의 인준 요구를 게시 이후에만 받는다.</li><li>촉발 사건: 붕괴 3년 열여섯 깃발에서 중앙 비상위원회가 해산되자, 여시온은 서남 독자 헌장 사본을 천왕과 금천에 동시에 전한다.</li><li>플레이어 개입: 회수된 사본을 되찾아 게시를 끝내거나, 세 장의 문구가 서로 다름을 밝혀 전령을 교체할 수 있다.</li></ul><h3 id="인물-기필호" tabindex="-1">인물 기필호 <a class="header-anchor" href="#인물-기필호" aria-label="Permalink to &quot;인물 기필호&quot;">​</a></h3><ul><li>소속: 서남제작동맹</li><li>직위: 패권전 제작 병참</li><li>성격: 공구 상자 수보다 숙련공의 교대 시간을 먼저 세고, 통일안의 이름을 군량 딱지로 붙이는 사람을 경계한다. 실리를 말하되 민가 전력을 병참으로 빼지 않는다.</li><li>개인 야망: 수리 규격 통일안이 무력 정복이 아니라 상호 수리권의 물자표로 남게 해, 작업반이 공병대로만 전환되지 않게 한다.</li><li>공포: 병참 열차가 차단문 전투조의 탄약칸으로 바뀌고, 제작규격동맹이 부품 봉쇄의 다른 이름이 되는 것.</li><li>통치 방식: 병참 출고는 평의회 추첨과 숙련 점수 공개 뒤에만 하고, 비밀 군수 칸은 발전 출력과 함께 잠근다.</li><li>핵심 관계: 최다인의 공병 작업반과 출고 순서를 다투고, 강민서의 제작동맹 통일안을 물자표로 옮기며, 서부 호송의 기바름과 부품 칸을 교환한다.</li><li>촉발 사건: 여름 이후 다섯 통일안이 경쟁하자, 기필호는 구로 병참 창고에서 수리 규격 물자만 남기고 군수 칸의 봉인을 거부한다.</li><li>플레이어 개입: 상호 수리권 물자를 채워 그의 봉인을 정당화하거나, 숨겨진 탄약칸을 폭로해 병참을 교체할 수 있다.</li></ul>',56)])])}const q=i(t,[["render",h]]);export{b as __pageData,q as default};
